"""Render audited immutable stages and cumulative costs into established site."""
import sys,json,html,re
from pathlib import Path
root=Path(__file__).resolve().parents[1];directory=root/'research/knot-classifier'
names=sys.argv[1:];stages=[]
for name in names:
    data=json.loads((directory/f'{name}-benchmark.json').read_text());audit=json.loads((directory/f'{name}-verification.json').read_text());assert audit['verified'];stages.append((name,data,audit))
parent=json.loads((directory/'lattice-blind-benchmark.json').read_text());cumulative={l['lane']:{'correct':l['correct'],'incorrect':l['incorrect'],'unknown':l['unknown'],'totalMs':l['totalMs'],'nodes':l['nodes'],'proofNodes':l['proofProbeAndValidationNodes']} for l in parent['lanes']}
sections=[]
def knot(k):
    head,index=k.split('_');return '\\('+head+'_{'+index+'}\\)'
def table(data):
    rows=''.join(f"<tr><td>{'Online GCTS' if l['learn'] else 'Brute force'}</td><td>{l['correct']} / {l['incorrect']} / {l['unknown']}</td><td>{l['totalMs']/1000:.2f}</td><td>{l['nodes']:,}</td><td>{l['proofProbeAndValidationNodes']:,}</td><td>{l['peakRssKiB']/1024:.1f}</td></tr>" for l in data['lanes'])
    return '<table><thead><tr><th>Lane</th><th>Correct / incorrect / unknown</th><th>Total seconds</th><th>Search expansions</th><th>Proof + validation nodes</th><th>Peak MiB</th></tr></thead><tbody>'+rows+'</tbody></table>'
for name,data,audit in stages:
    retry=data.get('stage')=='retry-six';m,b=data['lanes'];summaries={l['lane']:l for l in audit['lanes']};stats=summaries['marked']['stats'];bounds=data['bounds']
    if retry:
        title=f"Retry: {len(data['cases'])} remaining unknowns at {bounds['maxMs']/1000:g} seconds per query";identifier=name+'-results'
        intro='The unchanged inputs are every marked unknown from the preceding immutable stage, against the same complete 35-reference bank. Both lanes run every selected case, even when the brute lane had additional earlier unknowns. No query was replaced or rescrambled.'
        for l in data['lanes']:
            c=cumulative[l['lane']];c['correct']+=l['correct'];c['incorrect']+=l['incorrect'];c['unknown']-=l['correct']+l['incorrect'];c['totalMs']+=l['totalMs'];c['nodes']+=l['nodes'];c['proofNodes']+=l['proofProbeAndValidationNodes']
        extra='<p>Cumulative original 105-case outcomes, retaining all previous retry work: '+ '; '.join(f"{lane}: {c['correct']} correct / {c['incorrect']} incorrect / {c['unknown']} unknown, {c['totalMs']/1000:.2f} lane seconds, {c['nodes']:,} search expansions and {c['proofNodes']:,} proof/validation nodes" for lane,c in cumulative.items())+'. The brute lane’s other original unknowns have not been retried. Shared original preparation and every independent stage audit remain separate common costs.</p>'
    else:
        title='Scaling pilot: full prime reference bank through 12 crossings';identifier='blind-scaling-results'
        intro=f"Every query is tested against all {len(data['references']):,} prime reference types through twelve crossings. Queries cover the predeclared first and last corpus type at each crossing count nine through twelve, three independent eight-move scrambles each: {len(data['cases'])} queries across eight types. These eight bank references are independently eight-move scrambled; the remaining 2,969 references use canonical embeddings. This is a representative query pilot against a complete bank, not exhaustive query testing of all 2,977 types."
        extra='<p>Selected types: '+', '.join(knot(k) for k in data['selectedTypes'])+'. Neither their names, crossing counts, seeds, histories nor correct bank indices enter the search. Every query and reference is fixed before either lane runs.</p>'
    broader=('<p>This stage additionally applies whole-window continuation proofs to child discrepancy components larger than 48 edges, using the existing root catalog and its 64-node/sixteen-horizon probes. Per-component maximum proved bounds compose only across disjoint face alphabets. These broader child constraints are reported separately from local transfer; all their learning/validation costs and evidence are in the root channel.</p>' if bounds.get('wholeWindowChildren') else '')
    portfolio=('<p>Both lanes use a fair portfolio of neutral move-order seeds '+', '.join(map(str,bounds['searchSeeds']))+'. Each reference retains one root candidate; all ordering/contour contexts share the same aggregate time, node and live-state limits. These are generic permutations, with no knot label or learned ordering policy.</p>' if len(bounds.get('searchSeeds',[]))>1 else '')
    archive=m['proofArchive'];proofLinks=' · '.join('<a href=\"'+p['file']+'\">Proof archive part '+str(i+1)+'</a>' for i,p in enumerate(archive.get('files',[archive])))
    unknowns=', '.join(knot(data['cases'][r['caseIndex']]['evaluatorKnot'])+', seed '+str(data['cases'][r['caseIndex']]['seedIndex']) for r in m['runs'] if r['status']=='unknown') or 'none'
    types=list(dict.fromkeys(c['evaluatorKnot'] for c in data['cases']));rows=''.join('<tr><td>'+knot(k)+'</td><td>'+str(summaries['marked']['byType'][k]['correct'])+' / '+str(summaries['marked']['byType'][k]['unknown'])+'</td><td>'+str(summaries['brute']['byType'][k]['correct'])+' / '+str(summaries['brute']['byType'][k]['unknown'])+'</td></tr>' for k in types)
    sections.append(f'''<section id="{identifier}"><h2>{title}</h2>
<p><strong>Online GCTS: {m['correct']} correct / {m['incorrect']} incorrect / {m['unknown']} unknown. Brute force: {b['correct']} correct / {b['incorrect']} incorrect / {b['unknown']} unknown.</strong> {intro}</p>
<p>Matched aggregate budgets: {bounds['maxMs']/1000:g} seconds, {bounds['nodeCap']:,} expansions, {bounds['stateCap']:,} live visited states, sixteen moves and 240 unit edges per query. All incident lattice face locations remain available. Both lanes use the same fair resumable DFS, neutral seed and exact inventory memoization. The marked lane starts empty and reuses only its own online proofs across query knot types. No invariant, knot-specific ordering, patch restriction, saved markings or construction path is supplied.</p>
{table(data)}{extra}{broader}{portfolio}
<p>Elapsed lane totals include the full reference graph, failed references and contours, exact cache warmup, online probes and activation/transfer validation, JS certificate replay, cold initialization and archival/checkpoints. Shared preparation: {data['preparationMs']/1000:.2f} seconds. Independent stage audit: {audit['independentVerificationMs']/1000:.2f} seconds. These are reported separately. Brute-force unknowns prevent an equal-success speedup claim.</p>
<p>Root markings exclude {summaries['marked']['rootExcluded']:,} reference choices under the finite horizon. Local child markings eliminate {stats.get('extensionEliminations',0):,} of {stats.get('extensionCandidateCount',0):,} base-legal options in complete extension graphs; root proofs have {summaries['marked']['crossTypeRootApplications']:,} applications learned on earlier queries of different evaluator knot types. Whole-discrepancy root proofs and local supports of at most 48 edges are distinct. Unknown probes supply no hard exclusion.</p>
<p>Marked unknowns: {unknowns}. Independent Python checks {audit['provenanceMovies']} provenance movies, {audit['identificationMovies']} scored paths, {audit['extensionProofs']:,} extension proofs and {audit['resolvedLabels']:,} resolved cover labels, along with full bank coverage, fixed input selection, root composition and cost/catalog continuity.</p>
<table><thead><tr><th>Query type</th><th>GCTS correct / unknown</th><th>Brute correct / unknown</th></tr></thead><tbody>{rows}</tbody></table>
<p><a href="{name}-benchmark.json">Every input, outcome, cost and certificate</a> · {proofLinks} · <a href="{name}-verification.json">Independent stage audit</a> · <a href="lattice-blind-scaling-contract.json">Contract and limitations</a>.</p>
<p>This remains a declared point-valued graph-path adaptation of GCTS. The fixed projection and single-Reidemeister/routing author grammar remain inventory restrictions; no general lattice-isotopy completeness claim is made. Finite failures stay unknown. Arbitrary-input recognition, negative certificates, separate mirrors/composites and RL remain open.</p></section>''')
scale=next((d for _,d,_ in stages if d.get('stage')=='scale12'),None)
combined={}
for lane,c in cumulative.items():
    pilot=next((l for l in scale['lanes'] if l['lane']==lane),{}) if scale else {}
    combined[lane]={'original105':c,'pilotCorrect':pilot.get('correct',0),'pilotIncorrect':pilot.get('incorrect',0),'pilotUnknown':pilot.get('unknown',0),'pilotTotalMs':pilot.get('totalMs',0),'totalMs':c['totalMs']+pilot.get('totalMs',0),'nodes':c['nodes']+pilot.get('nodes',0),'proofNodes':c['proofNodes']+pilot.get('proofProbeAndValidationNodes',0)}
summary={'stages':[{'name':n,'cases':len(d['cases']),'correct':[l['correct'] for l in d['lanes']],'unknown':[l['unknown'] for l in d['lanes']]} for n,d,a in stages],'cumulativeOriginal105':cumulative,'combined':combined,'commonPreparationMs':parent['preparationMs']+sum(d['preparationMs'] for _,d,_ in stages),'independentAuditsMs':parent['independentVerification']['independentVerificationMs']+sum(a['independentVerificationMs'] for _,_,a in stages),'artifactFinalizationMs':sum(d.get('artifactFinalizationMs',0) for _,d,_ in stages)}
cm=cumulative['marked'];pm=scale['lanes'][0] if scale else {'correct':0,'incorrect':0,'unknown':0}
combinedRows=''.join(f"<tr><td>{'Online GCTS' if lane=='marked' else 'Brute force'}</td><td>{c['original105']['correct']} / {c['original105']['unknown']}</td><td>{c['pilotCorrect']} / {c['pilotUnknown']}</td><td>{c['original105']['totalMs']/1000:.2f}</td><td>{c['pilotTotalMs']/1000:.2f}</td><td>{c['totalMs']/1000:.2f}</td><td>{c['nodes']:,}</td><td>{c['proofNodes']:,}</td></tr>" for lane,c in combined.items())
overview=f'''<section id="blind-results" data-stage-overview="true"><h2>Current blind classification and total costs</h2>
<p><strong>The original 105 eight-crossing cases now have {cm['correct']} correct identifications, {cm['incorrect']} incorrect and {cm['unknown']} unknown.</strong> Every original unknown was retried unchanged. The newer pilot has {pm['correct']} correct, {pm['incorrect']} incorrect and {pm['unknown']} unknown across 24 independently scrambled queries at nine through twelve crossings, each against all 2,977 prime bank references. This pilot covers eight predeclared query types and three seeds each; it does not exhaustively test all 2,977 types.</p>
<table><thead><tr><th>Lane</th><th>Original 105 correct / unknown</th><th>Pilot 24 correct / unknown</th><th>Original + retry seconds</th><th>Pilot seconds</th><th>Combined lane seconds</th><th>Search expansions</th><th>Proof + validation nodes</th></tr></thead><tbody>{combinedRows}</tbody></table>
<p>All failed retries remain in these totals, including the unsuccessful ten-minute attempt. The final original unknown was found using a generic fair portfolio of neutral move orderings, with identical orderings and aggregate budgets in both lanes. All lattice move locations remain unrestricted. Shared input preparation totals {summary['commonPreparationMs']/1000:.2f} seconds; independent stage audits total {summary['independentAuditsMs']/1000:.2f} seconds; new-stage artifact assembly/compression totals {summary['artifactFinalizationMs']/1000:.2f} seconds before final manifest writes. These common costs are separate from the lane totals. Brute-force unknowns prevent an equal-success speedup claim.</p>
<p><a href="#blind-scaling-results">Full twelve-crossing-bank pilot</a> · <a href="#lattice-blind-portfolio900-results">Final original-case retry</a> · <a href="#blind-original-results">Immutable original experiment</a> · <a href="lattice-blind-scaling-summary.json">Machine-readable totals</a>.</p></section>'''
page=directory/'lattice-classifier.html';text=page.read_text()
text=re.sub(r'<section id="blind-results" data-stage-overview="true">.*?</section>\s*','',text,flags=re.S)
for identifier in [name+'-results' for name in names]+['blind-scaling-results']:
    text=re.sub(r'<section id="'+re.escape(identifier)+r'">.*?</section>\s*','',text,flags=re.S)
text=text.replace('<section id="blind-results">','<section id="blind-original-results">',1)
text=text.replace('<section id="blind-original-results">',overview+'\n'+'\n'.join(sections)+'\n<section id="blind-original-results">',1)
text=re.sub(r'\\\((\d+)_(\d+)\\\)',lambda m:'\\('+m[1]+'_{'+m[2]+'}\\)',text)
text=text.replace('((11,13,17))',r'\((11,13,17)\)').replace('incompatible (m)-values',r'incompatible \(m\)-values')
page.write_text(text)
(directory/'lattice-blind-scaling-summary.json').write_text(json.dumps(summary,indent=2)+'\n')
readme=directory/'README.md';old=readme.read_text();old=re.sub(r'^> \*\*Current blind-classification stages:.*?\n\n','',old,flags=re.S)
old=old.replace('> **Blind classification:**','> **Original ten-second blind classification:**',1)
c=cumulative['marked'];scale=next((d for _,d,_ in stages if d.get('stage')=='scale12'),None)
pilot=(' The full 2,977-prime bank pilot has '+str(scale['lanes'][0]['correct'])+' correct / '+str(scale['lanes'][0]['incorrect'])+' incorrect / '+str(scale['lanes'][0]['unknown'])+' unknown across 24 independent queries of eight predeclared types at 9–12 crossings; this is representative query coverage, not exhaustive testing of all types.' if scale else '')
readme.write_text('> **Current blind-classification stages:** Original 105 cases plus unchanged unknown retries: '+str(c['correct'])+' correct / '+str(c['incorrect'])+' incorrect / '+str(c['unknown'])+' unknown.'+pilot+' All lattice face locations remain available. Markings are learned online and reused across query types; complete root and child-window proof scopes, matched brute-force costs, and every prior retry cost are reported. [Live stage results](lattice-classifier.html#blind-scaling-results), [summary](lattice-blind-scaling-summary.json), [contract](lattice-blind-scaling-contract.json).\n\n'+old)
print(json.dumps(summary))
